package de.galeriesync.sync
import android.content.ContentResolver
import android.provider.MediaStore
data class LocalMedia(val uri: android.net.Uri,val relativePath:String,val size:Long,val displayName:String,val modified:Long=0L)
data class MediaFolder(val path:String,val name:String,val count:Int,val previews:List<android.net.Uri>)
class MediaScanner(private val resolver:ContentResolver){
 fun folders():List<String> = scan().map{it.relativePath.substringBeforeLast('/', "").trim('/')}.filter{it.isNotBlank()}.distinct().sorted()
 fun folderMedia():List<MediaFolder> = scan().groupBy{it.relativePath.substringBeforeLast('/',"").trim('/')}.filterKeys{it.isNotBlank()}.map{(path,items)->MediaFolder(path,path.substringAfterLast('/'),items.size,items.take(4).map{it.uri})}.sortedBy{it.name.lowercase()}
 fun scan(selectedFolders:Set<String> = emptySet()):List<LocalMedia>{val result=mutableListOf<LocalMedia>();val collections=listOf(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,MediaStore.Video.Media.EXTERNAL_CONTENT_URI);for(collection in collections){val projection=arrayOf(MediaStore.MediaColumns._ID,MediaStore.MediaColumns.DISPLAY_NAME,MediaStore.MediaColumns.SIZE,MediaStore.MediaColumns.RELATIVE_PATH,MediaStore.MediaColumns.DATE_MODIFIED);resolver.query(collection,projection,null,null,MediaStore.MediaColumns.DATE_MODIFIED+" DESC")?.use{c->val id=c.getColumnIndexOrThrow(MediaStore.MediaColumns._ID);val name=c.getColumnIndexOrThrow(MediaStore.MediaColumns.DISPLAY_NAME);val size=c.getColumnIndexOrThrow(MediaStore.MediaColumns.SIZE);val rel=c.getColumnIndex(MediaStore.MediaColumns.RELATIVE_PATH);val modified=c.getColumnIndex(MediaStore.MediaColumns.DATE_MODIFIED);while(c.moveToNext()){val n=c.getString(name)?:continue;val r=if(rel>=0)c.getString(rel).orEmpty() else "";result+=LocalMedia(android.content.ContentUris.withAppendedId(collection,c.getLong(id)),r+n,c.getLong(size),n,if(modified>=0)c.getLong(modified)*1000L else 0L)}}};return result.distinctBy{it.relativePath}.filter{m->selectedFolders.isEmpty()||selectedFolders.any{folder->m.relativePath.trimStart('/').startsWith(folder.trim('/')+"/")}}}
}